const {demand}=require('./safety');
const {websiteType}=require('./design');
const esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const file=p=>p==='home'?'index.html':p+'.html';
const json=v=>JSON.stringify(v).replace(/</g,'\\u003c');
function assetList(input=[]){
 demand(Array.isArray(input)&&input.length<=20,'At most 20 asset references are supported',400);
 return input.map(a=>{
  demand(a&&['logo','hero','service','product','gallery','icon'].includes(a.role)&&['existing','uploaded','placeholder'].includes(a.source),'Invalid asset role/source',400);
  demand(a.source==='placeholder'||typeof a.path==='string'&&a.path.length<=300&&!/[<>"'\\]|\.\.|^\/|^data:|^javascript:/i.test(a.path)&&(/^[a-z0-9_/-]+\.(png|jpe?g|webp|avif|svg)$/i.test(a.path)||/^https:\/\//.test(a.path)),'Use a safe existing asset reference',400);
  if(/^https:\/\//.test(a.path||'')){const u=new URL(a.path);demand(!u.username&&!u.password&&!u.search&&!u.hash,'Use an asset URL without credentials/query',400);}
  demand(!a.alt||typeof a.alt==='string'&&a.alt.length<=300,'Invalid asset alt text',400);
  return {role:a.role,source:a.source,path:a.source==='placeholder'?'':a.path,alt:a.alt||'',status:a.source==='placeholder'?'DESIGN_PLACEHOLDER':'REFERENCE_ONLY_REQUIRES_VERIFICATION'};
 });
}
function build(req,files,designLock){
 demand(designLock?.state==='APPROVED','Approve a design before generating production files');
 const spec=designLock.layoutSpecification,type=websiteType(req.websiteType),changes=[];
 const add=(name,content,reason)=>{demand(!Object.hasOwn(files,name),'CREATE_NEW conflicts with existing files; use UPGRADE_EXISTING');changes.push({file:name,content,reason,operation:'CREATE'});};
 const items=req.productsServices.split(/\n|;/).map(s=>s.trim()).filter(Boolean).slice(0,8);
 const assets=req.assetReferences||[];
 const image=(role,lazy=true)=>{const a=assets.find(a=>a.role===role&&a.path);return a?`<img src="${esc(a.path)}" alt="${esc(a.alt)}" width="1200" height="800" style="aspect-ratio:3/2;object-fit:cover" ${lazy?'loading="lazy"':'fetchpriority="high"'}>`:`<div class="design-art" role="img" aria-label="Abstract design placeholder"><span>DESIGN PLACEHOLDER</span><div class="art-shape"></div><small>Client imagery can be supplied for review.</small></div>`;};
 const contact=[req.address,req.location].filter(Boolean).map(esc).join(' · ');
 const contacts=`${contact?`<p>${contact}</p>`:''}${req.phone?`<p><a href="tel:${esc(req.phone.replace(/[^+\d]/g,''))}">${esc(req.phone)}</a></p>`:''}${req.email&&/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(req.email)?`<p><a href="mailto:${esc(req.email)}">${esc(req.email)}</a></p>`:''}`;
 const cta=req.pages.includes('contact')?'contact.html':'#contact';
 const nav=req.pages.map(p=>`<a href="${file(p)}">${esc(p.replace(/-/g,' '))}</a>`).join('');
 const schema={'@context':'https://schema.org','@graph':[{'@type':req.address?'LocalBusiness':'Organization',name:req.businessName,...(req.website?{url:req.website}:{}),...(req.address?{address:req.address}:{}),...(req.phone?{telephone:req.phone}:{})}]};
 if(req.productsServices&&['SERVICE','INTERIOR','CONSTRUCTION','AGENCY','BEAUTY','ASTROLOGY','EVENT'].includes(req.websiteType))for(const name of items)schema['@graph'].push({'@type':'Service',name,provider:{'@type':'Organization',name:req.businessName}});
 if(['ECOMMERCE','CATALOGUE'].includes(req.websiteType))for(const name of items)schema['@graph'].push({'@type':'Product',name});
 const cards=items.length?items.map((item,i)=>`<article class="card">${assets.filter(a=>a.role===(req.websiteType==='ECOMMERCE'||req.websiteType==='CATALOGUE'?'product':'service')&&a.path)[i]?`<img src="${esc(assets.filter(a=>a.role===(req.websiteType==='ECOMMERCE'||req.websiteType==='CATALOGUE'?'product':'service')&&a.path)[i].path)}" alt="${esc(assets.filter(a=>a.role===(req.websiteType==='ECOMMERCE'||req.websiteType==='CATALOGUE'?'product':'service')&&a.path)[i].alt)}" width="600" height="400" loading="lazy">`:''}<span class="eyebrow">${String(i+1).padStart(2,'0')}</span><h3>${esc(item)}</h3><p>Contact ${esc(req.businessName)} to discuss ${esc(item)} and your specific requirements.</p><a href="${cta}">Enquire about ${esc(item)}</a></article>`).join(''):'<article class="card"><h3>Details awaiting your input</h3><p>Add verified services or products before publishing this section.</p></article>';
 const summary={home:req.description,about:`About ${req.businessName}: ${req.description}`,services:`Services at ${req.businessName}: ${req.productsServices||'Verified service details pending client input.'}`,products:`Products from ${req.businessName}: ${req.productsServices||'Verified product details pending client input.'}`,contact:`Contact ${req.businessName}${req.location?' in '+req.location:''} to discuss your requirements. ${[req.address,req.phone,req.email].filter(Boolean).join(' · ')}`,gallery:`Visual gallery for ${req.businessName}. Client-supplied imagery and captions require review before publication.`,projects:`Selected projects by ${req.businessName}. Only verified project information will be published.`,'privacy-policy':`Privacy information for ${req.businessName}. This policy requires client and legal review before publication.`};
 for(const page of req.pages){
  const label=page==='home'?req.businessName:page.replace(/-/g,' '),title=page==='home'?req.businessName:`${label} | ${req.businessName}`;
  const url=req.website?req.website+'/'+(page==='home'?'':file(page)):'';
  const description=summary[page].slice(0,170);
  const pageSchema=structuredClone(schema);
  if(req.website&&page!=='home')pageSchema['@graph'].push({'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:req.businessName,item:req.website+'/'},{'@type':'ListItem',position:2,name:label,item:url}]});
  const hero=`<section class="hero"><div class="hero-copy"><p class="eyebrow">${esc(type.label)}${req.location?' · '+esc(req.location):''}</p><h1>${esc(label)}</h1><p class="lead">${esc(summary[page])}</p><a class="button" href="${cta}">${esc(spec.cta)}</a></div>${image('hero',false)}</section>`;
  const section=(name,body)=>`<section class="section"><div class="section-heading"><p class="eyebrow">${esc(req.businessName)}</p><h2>${esc(name)}</h2></div>${body}</section>`;
  let body;
  if(page==='home')body=hero+spec.sections.map((name,i)=>section(name,i===0?`<div class="cards">${cards}</div>`:i===spec.sections.length-1?`<div class="contact-panel"><p>Tell us what you need. We will use your enquiry to discuss the next steps directly.</p>${contacts||'<p>Verified contact details pending client input.</p>'}<a class="button" href="${cta}">${esc(spec.cta)}</a></div>`:`<div class="feature"><h3>${esc(name)} at ${esc(req.businessName)}</h3><p>${esc(i===1?req.description:'Specific '+name.toLowerCase()+' details require client input and approval before publication.')}</p></div>`)).join('');
  else if(page==='services'||page==='products')body=hero+section(label,`<div class="cards">${cards}</div>`);
  else if(page==='contact')body=hero+section('Start a conversation',`<div id="contact" class="contact-panel">${contacts||'<p>Contact details pending client review. No submission backend is configured.</p>'}<p>When making an enquiry, describe what you need and the questions you would like to discuss. Include the service or product of interest, your preferred contact method and any relevant requirements.</p><p>Confirm suitability, availability, scope and next steps directly before making a decision. Avoid sending passwords, payment information or sensitive documents in an initial enquiry. Ask for the preferred channel for sharing detailed information. Any timeline, quotation or appointment must be confirmed directly; this website does not promise availability or process payments.</p></div>`);
  else if(page==='gallery'||page==='projects')body=hero+section(label,assets.filter(a=>a.role==='gallery'&&a.path).map(a=>`<figure><img src="${esc(a.path)}" alt="${esc(a.alt)}" width="1200" height="800" loading="lazy"><figcaption>${esc(a.alt||'Caption requires client review.')}</figcaption></figure>`).join('')||'<p>Verified images, project details and captions pending client input.</p>');
  else body=hero+section(page==='about'?'Our approach':'Client review required',`<div class="feature"><p>${esc(summary[page])}</p><p>${page==='about'?'For questions about suitability, availability and requirements, please contact '+esc(req.businessName)+' directly.':'This page is an editable draft and must be reviewed before publication.'}</p></div>`);
  add(file(page),`<!doctype html>\n<html lang="${req.language}"><head><meta charset="utf-8"><link rel="icon" href="data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2032%2032'%3E%3Ccircle%20cx='16'%20cy='16'%20r='12'%20fill='%23155e54'/%3E%3C/svg%3E"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}">${url?`<link rel="canonical" href="${esc(url)}"><meta property="og:url" content="${esc(url)}">`:''}<meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><link rel="stylesheet" href="styles.css"><script defer src="site.js"></script><script type="application/ld+json">${json(pageSchema)}</script></head><body class="layout-${spec.layout} nav-${spec.nav} cards-${spec.cards} mobile-${spec.mobile} footer-${spec.footer}"><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="index.html">${assets.find(a=>a.role==='logo'&&a.path)?`<img src="${esc(assets.find(a=>a.role==='logo'&&a.path).path)}" alt="${esc(assets.find(a=>a.role==='logo'&&a.path).alt)}" width="96" height="96" style="width:3rem;height:3rem;object-fit:contain">`:''}${esc(req.businessName)}</a><nav aria-label="Main navigation">${nav}</nav></header><main id="main">${body}</main><footer id="contact"><div><strong>${esc(req.businessName)}</strong><p>${esc(req.location)}</p></div><nav aria-label="Footer navigation">${nav}</nav><div>${contacts}</div></footer></body></html>\n`,'Generate page-specific content/SEO and composition from approved design '+designLock.selectedVariantId);
 }
 const space={Compact:'3rem',Balanced:'5rem',Spacious:'7rem'}[spec.density];
 add('styles.css',`:root{--primary:${spec.primary};--accent:${spec.accent};--paper:${spec.background};--ink:${spec.ink};--radius:${spec.corners==='Sharp'?'0':'1.4rem'};--space:${space};color:var(--ink);background:var(--paper);font-family:system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;overflow-wrap:anywhere}a{color:inherit;text-underline-offset:.25em}a:focus-visible{outline:3px solid var(--accent);outline-offset:5px}img{width:100%;max-width:100%;height:auto;border-radius:var(--radius)}.site-header,main,footer{max-width:1280px;margin:auto;padding-inline:clamp(1.2rem,5vw,5rem)}.site-header{padding-block:1.5rem;display:flex;justify-content:space-between;gap:2rem;align-items:center}.brand{font-size:1.2rem;font-weight:800;text-decoration:none}nav{display:flex;gap:1.2rem;flex-wrap:wrap;text-transform:capitalize;font-size:.9rem}.hero{padding-block:var(--space);display:grid;grid-template-columns:1.1fr 1fr;align-items:center;gap:4rem;min-height:70vh}h1,h2,h3{line-height:1.08;text-wrap:balance}h1{font-size:clamp(2.6rem,6vw,${spec.heroScale==='large'?'7rem':'6rem'});margin:.4em 0;font-family:${/serif/i.test(spec.typography)?'Georgia,serif':'inherit'}}h2{font-size:clamp(2rem,4vw,3.5rem)}h3{font-size:1.35rem}.lead{font-size:1.15rem;line-height:1.8;max-width:55ch}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:.75rem;font-weight:800}.button{display:inline-flex;background:var(--primary);color:${spec.buttonInk||'#fff'};padding:1rem 1.5rem;border-radius:var(--radius);font-weight:700;text-decoration:none;margin-top:1rem}.design-art{min-height:330px;padding:2rem;background:color-mix(in srgb,var(--primary) 15%,var(--paper));display:flex;flex-direction:column;justify-content:space-between;border-radius:var(--radius)}.design-art span,.design-art small{font-size:.7rem}.art-shape{height:160px;width:70%;align-self:center;border:18px solid var(--primary);border-radius:50% 50% 0 0;transform:rotate(-12deg)}.section{padding-block:calc(var(--space)/1.3);border-top:1px solid color-mix(in srgb,var(--ink) 18%,transparent)}.section-heading{max-width:44rem}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.5rem}.card,.feature,.contact-panel{padding:2rem;border:1px solid color-mix(in srgb,var(--ink) 20%,transparent);border-radius:var(--radius)}.card p,.feature p{line-height:1.8}.cards-image-led .card{border:0;background:color-mix(in srgb,var(--primary) 12%,var(--paper));min-height:280px}.cards-numbered .card{border-top:5px solid var(--primary)}footer{padding-block:3rem;display:grid;grid-template-columns:1fr 1fr 1fr;gap:2rem}footer p{line-height:1.6}.footer-statement footer{grid-template-columns:1fr;text-align:center}.footer-statement footer strong{font-size:2.5rem}.footer-statement footer nav{justify-content:center}.nav-centered .site-header{flex-direction:column}.layout-poster .hero{grid-template-columns:1fr;text-align:center}.layout-poster .hero-copy{max-width:850px;margin:auto}.layout-poster .lead{margin-inline:auto}.layout-poster .design-art{min-height:400px}.layout-stacked .hero{grid-template-columns:1fr 1.3fr}.layout-stacked h1{font-family:system-ui,sans-serif;font-size:clamp(2.5rem,5vw,4.5rem)}.skip{position:absolute;left:-9999px}.skip:focus{left:1rem;top:1rem;background:var(--paper);padding:1rem;z-index:10}@media(max-width:720px){.site-header{align-items:flex-start;flex-direction:column;gap:1rem}.hero,.layout-stacked .hero{grid-template-columns:1fr;gap:2rem;min-height:auto;padding-block:3rem}.cards{grid-template-columns:1fr}.section{padding-block:3rem}footer{grid-template-columns:1fr}.mobile-cta-first .button{width:100%;justify-content:center}.mobile-full-bleed .design-art{border-radius:0;min-height:300px}.mobile-simple .design-art{min-height:180px}.mobile-simple .art-shape{height:80px}nav{gap:1rem}.design-art{min-height:240px}}${spec.animation!=='None'?`@keyframes intro{from{opacity:.7;transform:translateY(${spec.animation==='Moderate'?'16':'6'}px)}to{opacity:1;transform:none}}.hero-copy{animation:intro .6s ease both}`:''}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important;animation:none!important}}\n`,'Responsive tokens, typography, hierarchy, cards and mobile layout from approved design');
 add('site.js',"'use strict';\n// No tracking, fictitious forms, arbitrary scripts or runtime dependencies.\n",'Dependency-free website behaviour');
 add('design-review.json',JSON.stringify({variant:designLock.selectedVariantId,revision:designLock.revision,spec},null,2),'Optional portable approved-design reference; may be rejected without breaking the website');
 const manifest={pages:req.pages.map(file),domain:req.website||'',required:['styles.css','site.js','robots.txt',...(req.website?['sitemap.xml']:[])]};
 add('validate-site.js',`const manifest=${JSON.stringify(manifest)};\n(${validateStatic.toString()})(manifest);\n`,'Read-only structural HTML, metadata, links, JS and crawl-file validation');
 add('package.json',JSON.stringify({name:'client-website',private:true,version:'1.0.0',scripts:{typecheck:'node validate-site.js',build:'node validate-site.js'}},null,2)+'\n','Real static-site integrity validation; no compilation or dependency installation');
 add('robots.txt',`User-agent: *\nAllow: /\n${req.website?'Sitemap: '+req.website+'/sitemap.xml\n':''}`,'Explicitly review public crawl policy');
 if(req.website)add('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${req.pages.map(p=>`<url><loc>${esc(req.website+'/'+(p==='home'?'':file(p)))}</loc></url>`).join('')}</urlset>\n`,'Sitemap of selected approved pages on verified domain');
 return changes;
}
function validateStatic(manifest){
 const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');const fail=[];const titles=new Set(),descriptions=new Set();
 const read=f=>{try{return fs.readFileSync(f,'utf8')}catch{fail.push('Missing file: '+f);return ''}};
 for(const required of [...manifest.pages,...manifest.required])if(!fs.existsSync(required))fail.push('Missing required file: '+required);
 for(const page of manifest.pages){const html=read(page);const title=html.match(/<title>([^<]+)<\/title>/i)?.[1],description=html.match(/<meta name="description" content="([^"]+)"/i)?.[1];
  for(const [value,seen,name]of [[title,titles,'title'],[description,descriptions,'description']]){if(!value||seen.has(value))fail.push(page+': missing/duplicate '+name);seen.add(value);}
  if(!/<!doctype html>/i.test(html)||!/<html\b/i.test(html)||!/<head>/i.test(html)||!/<body\b/i.test(html)||!/<\/html>/i.test(html))fail.push(page+': incomplete HTML document');
  if((html.match(/<h1\b/g)||[]).length!==1||!/<meta name="viewport"/i.test(html))fail.push(page+': heading/viewport missing');
  const stack=[],voids=new Set(['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr']);
  const markup=html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<!--[\s\S]*?-->/g,'');
  for(const t of markup.matchAll(/<(\/?)([a-z][\w-]*)\b[^>]*>/gi)){const tag=t[2].toLowerCase();if(voids.has(tag))continue;if(t[1]){if(stack.pop()!==tag)fail.push(page+': unbalanced '+tag)}else stack.push(tag);}
  if(stack.length)fail.push(page+': unclosed HTML elements');
  for(const a of html.matchAll(/(?:href|src)="([^"]+)"/g)){const value=a[1].split(/[?#]/)[0];if(!value||/^[a-z]+:/i.test(value))continue;const target=path.resolve(path.dirname(page),value);if(!target.startsWith(process.cwd()+path.sep)||!fs.existsSync(target))fail.push(page+': unresolved local reference '+value);}
  if(manifest.domain&&!html.includes('rel="canonical"'))fail.push(page+': missing canonical');
  for(const s of html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g))try{JSON.parse(s[1])}catch{fail.push(page+': invalid schema JSON')}
 }
 const check=cp.spawnSync(process.execPath,['--check','site.js'],{encoding:'utf8',windowsHide:true});if(check.status!==0)fail.push('JavaScript syntax failed');
 if(manifest.domain){const map=read('sitemap.xml'),robots=read('robots.txt');if(!map.includes('<urlset')||!robots.includes('Sitemap: '+manifest.domain+'/sitemap.xml'))fail.push('Crawl files inconsistent');for(const p of manifest.pages)if(!map.includes(manifest.domain+'/'+(p==='index.html'?'':p)))fail.push('Sitemap missing '+p);}
 if(fail.length){console.error(fail.join('\n'));process.exitCode=1;}else console.log('PASS static integrity: HTML, unique metadata, local references, required files, schema, JS and crawl files. Runtime/performance NOT MEASURED.');
}
module.exports={build,assetList,validateStatic};
